from fractions import Fraction
def analyze_counter(before,after,interval_seconds,link_bps,width):
    if type(width) is not int or width not in (32,64):raise ValueError("Counter32 or Counter64 required")
    if any(type(v) is not int or v<=0 for v in (interval_seconds,link_bps)):raise ValueError("positive integer interval and link rate required")
    modulus=1<<width
    for sample in (before,after):
        if not isinstance(sample,dict):raise ValueError("snapshot object required")
        for name in ("counter","uptime","discontinuity"):
            if type(sample.get(name)) is not int or sample[name]<0:raise ValueError("nonnegative integer fields required")
        if sample["counter"]>=modulus:raise ValueError("counter outside declared width")
    if after["uptime"]<before["uptime"] or after["discontinuity"]!=before["discontinuity"]:
        return {"status":"discontinuity","delta_octets":None,"action":"collect a new baseline; do not repair this difference as a wrap"}
    delta=(after["counter"]-before["counter"])%modulus
    maximum=(link_bps*interval_seconds)//8
    if delta>maximum:
        return {"status":"inconsistent_sample","delta_octets":None,"action":"verify identity, interval and link capacity"}
    if delta+modulus<=maximum:
        return {"status":"ambiguous_wrap_count","delta_octets":None,"action":"collect ifHCInOctets with a bounded interval; missing historic wraps cannot be inferred"}
    rate=Fraction(delta*8,interval_seconds)
    return {"status":"bounded_rate","delta_octets":delta,"rate_bps_numerator":rate.numerator,"rate_bps_denominator":rate.denominator}
```

