import ipaddress,re
def audit_engines(rows):
    if not isinstance(rows,list):raise ValueError("one finite observation batch required")
    groups={};seen=set()
    for row in rows:
        if not isinstance(row,dict):raise ValueError("observation object required")
        if not isinstance(row.get("address"),str):raise ValueError("IP literal text required")
        try:address=str(ipaddress.ip_address(row.get("address")))
        except ValueError as exc:raise ValueError("IP literal required") from exc
        if address in seen:raise ValueError("one authoritative sample per address")
        seen.add(address);engine=row.get("engine_id")
        if not isinstance(engine,str):raise ValueError("hex engine ID required")
        engine=engine.lower().removeprefix("0x")
        if not re.fullmatch(r"[0-9a-f]{10,64}",engine) or len(engine)%2 or set(engine) in ({'0'},{'f'}):raise ValueError("engine ID must contain 5 to 32 non-reserved octets")
        if any(type(row.get(k)) is not int or not 0<=row[k]<(1<<31) for k in ("engine_boots","engine_time")):raise ValueError("invalid authoritative engine timing")
        groups.setdefault(engine,[]).append((address,row["engine_boots"],row["engine_time"]))
    result=[]
    for engine,samples in sorted(groups.items()):
        if len(samples)>1:
            result.append({"engine_id":engine,"addresses":sorted(s[0] for s in samples),
                "state_mismatch":len({(s[1],s[2]) for s in samples})>1,
                "action":"assign vendor-supported unique engine IDs; review localized SNMPv3 keys and refresh supported poller cache; verify both devices continuously and after reboot"})
    return {"duplicate_engines":result,"credentials_exported":False,"devices_changed":False}
```

